/**
 * The text of a key, each {name} filled with the value of that name. A name with
 * no value stays as written, so the gap shows.
 *
 * @param key the key of the text.
 * @param values the value of each placeholder, by name.
 * @param locale the locale tag (pt-BR): its own table, else its language, else English.
 */
export function say(key: WordKey, values: Record<string, string | number> = {}, locale = 'en'): string {
  const tag = locale.toLowerCase()
  const texts = translations[tag] ?? translations[tag.split('-')[0] ?? ''] ?? english
  return texts[key].replace(/\{([a-z][A-Za-z0-9]*)\}/g, (whole: string, name: string) =>
    name in values ? String(values[name]) : whole,
  )
}
